  captions: [[0.0, "Red lines up west of the cone and blue east of it, behind the 35-yard line. The coach and cone are in the middle of the field."], [0.6, "The coach rolls a ball about ten yards up the field."], [1.0, "Two players from each team go out and fight for it."], [3.2, "Red wins the ground ball, so red is on offense for the whole round."], [3.6, "The next red player pops out for a free pass."], [6.2, "Free pass! Now it is 3 on 2."], [12.2, "Red has a shot and takes it: goal! The goalie went the other way."], [14.2, "The coach calls \"Release a defender!\" The next defender joins to make it even: now 3 on 3."], [14.5, "Everyone gets back to the middle for the next ball."], [19.2, "The coach says \"New ball!\" and gives the offensive player nearest the 35 a free ball."], [20.2, "The offense goes again."], [28.2, "Red has a shot and takes it, but it goes wide and rolls behind."], [30.2, "The coach calls \"Release!\" The next player from each team joins: now 4 on 4."], [30.5, "Everyone gets back to the middle for the next ball."], [35.2, "The coach says \"New ball!\" and gives the offensive player nearest the 35 a free ball."], [36.2, "The offense goes again."], [42.2, "Red has a shot and takes it: the goalie makes the save."], [43.5, "The goalie has it and throws it back to the coach at the cone."], [44.2, "The coach calls \"Release!\" The next player from each team joins: now 5 on 5."], [44.5, "Everyone gets back to the middle for the next ball."], [49.2, "The coach says \"Ball in!\" and gives the offensive player nearest the 35 a free ball."], [50.2, "The offense goes again."], [57.2, "Red has a shot and takes it: goal! The goalie went the other way."], [59.58, "The coach calls \"Reset!\" and everyone goes back to the lines."]],
